import React, { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";
import "../css/LeaveRequest.css";

const LeaveRequests = () => {
  const [leaveRequests, setLeaveRequests] = useState([]);

  useEffect(() => {
    fetchLeaveRequests();
  }, []);

  const fetchLeaveRequests = async () => {
    try {
      const response = await axios.get("http://localhost:9090/api/leave-requests");
      setLeaveRequests(response.data.reverse()); 
    } catch (error) {
      console.error("İzin talepleri alınırken hata oluştu:", error);
    }
  };

  // ✅ İzin talebini silme fonksiyonu
  const deleteLeaveRequest = async (id) => {
    if (!window.confirm("Bu izin talebini silmek istediğine emin misin?")) return;

    try {
      await axios.delete(`http://localhost:9090/api/leave-requests/${id}`);
      setLeaveRequests(leaveRequests.filter((request) => request.id !== id)); 
    } catch (error) {
      console.error("İzin talebi silinirken hata oluştu:", error);
    }
  };

  return (
    <div className="leave-requests-container">
      <h1 className="leave-requests-title">Geçmiş İzin Talepleri</h1>
      
      <table className="leave-requests-table">
        <thead>
          <tr>
            <th>Çalışan</th>
            <th>E-posta</th>
            <th>Departman</th>
            <th>Talep Edilen Gün</th>
            <th>Kalan İzin</th>
            <th>Detay</th>
            <th>Sil</th> {/* ✅ Yeni eklenen "Sil" sütunu */}
          </tr>
        </thead>
        <tbody>
          {leaveRequests.length > 0 ? (
            leaveRequests.map((request) => (
              <tr key={request.id}>
                <td>{request.employee.name} {request.employee.surname}</td>
                <td>{request.employee.email}</td>
                <td>{request.employee.department}</td>
                <td>{request.leaveDaysRequested} Gün</td>
                <td>{request.employee.leaveDays} Gün</td>
                <td>
                  <Link to={`/leave-requests/${request.employee.id}`}>
                    <button className="detail-button">Detay</button>
                  </Link>
                </td>
                <td>
                  <button className="delete-button" onClick={() => deleteLeaveRequest(request.id)}>Sil</button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="7">İzin talebi bulunamadı.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default LeaveRequests;
